import numpy as np
lines = open('initial.xyz').read().splitlines()
n = int(lines[0])
sym=[]; pos=[]
for l in lines[2:2+n]:
    p=l.split(); sym.append(p[0]); pos.append([float(x) for x in p[1:4]])
pos=np.array(pos)
# find close contacts < 1.6 A between heavy atoms (rough clash check)
heavy=[i for i,s in enumerate(sym) if s!='H']
clash=[]
for a,i in enumerate(heavy):
    for j in heavy[a+1:]:
        d=np.linalg.norm(pos[i]-pos[j])
        if d<1.55: clash.append((i,sym[i],j,sym[j],round(d,2)))
print("close heavy-heavy (<1.55A):")
for c in clash: print(c)
# H-heavy clashes
clash2=[]
for i,s in enumerate(sym):
    if s=='H':
        for j in heavy:
            d=np.linalg.norm(pos[i]-pos[j])
            if d<1.0: clash2.append((i,j,round(d,2)))
print("H-heavy <1.0A:", clash2[:20])
